// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.function.xsd;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.junit.jupiter.api.Test;

class BooleanCastTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private final BooleanCast function = new BooleanCast();

	@Test
	void acceptsDerivedIntegersOutsideTheLongRange() {
		Literal positive = VF.createLiteral("9223372036854775808", XSD.NON_NEGATIVE_INTEGER);
		Literal negative = VF.createLiteral("-9223372036854775809", XSD.NON_POSITIVE_INTEGER);

		assertTrue(function.evaluate(VF, positive).booleanValue());
		assertTrue(function.evaluate(VF, negative).booleanValue());
	}

	@Test
	void finiteNonZeroFloatingPointValuesAreTrue() {
		assertTrue(function.evaluate(VF, VF.createLiteral(1.0f)).booleanValue());
		assertTrue(function.evaluate(VF, VF.createLiteral(-1.0d)).booleanValue());
	}

	@Test
	void nanAndSignedZeroAreFalse() {
		assertFalse(function.evaluate(VF, VF.createLiteral(Float.NaN)).booleanValue());
		assertFalse(function.evaluate(VF, VF.createLiteral(Double.NaN)).booleanValue());
		assertFalse(function.evaluate(VF, VF.createLiteral(-0.0f)).booleanValue());
		assertFalse(function.evaluate(VF, VF.createLiteral(-0.0d)).booleanValue());
	}

	@Test
	void decimalZerosAreFalseRegardlessOfScale() {
		assertFalse(function.evaluate(VF, VF.createLiteral("0.0", XSD.DECIMAL)).booleanValue());
		assertFalse(function.evaluate(VF, VF.createLiteral("-0.000", XSD.DECIMAL)).booleanValue());
	}
}
